import { useState } from 'react';

function TextMirror() {
  const [text, setText] = useState('');

  return (
    <div>
      <input 
        type="text" 
        value={text} 
        onChange={(e) => setText(e.target.value)}
        placeholder="Type something..."
      />
      <p>{text}</p>
    </div>
  );
}

export default TextMirror;
